import { useBreakpoints } from '@rocket.chat/fuselage-hooks';
import { styled, View } from '@tamagui/web';
import type { AllHTMLAttributes } from 'react';

import { Box } from '../Box';

export type CardProps = {
	horizontal?: boolean;
	hero?: boolean;
	clickable?: boolean;
} & Omit<AllHTMLAttributes<HTMLElement>, 'is'>;

// generated by scripts/generate-frame-values.mts from @rocket.chat/fuselage-tokens, do not edit

// Declared where they render: zero-runtime only erases a `styled()` whose every use is in its own module
const CardFrame = styled(View, {
	render: 'div',
	display: 'flex',
	flexDirection: 'row',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	color: 'var(--rcx-card-color, var(--rcx-color-font-default, #2f343d))',
	borderRadius: 'var(--rcx-border-radius-large, 0.5rem)',
	backgroundColor: 'var(--rcx-card-background-color, var(--rcx-color-surface-light, #ffffff))',
	variants: {
		layout: {
			'horizontal': {
				alignItems: 'center',
				padding: '12px',
				gap: '16px',
			},
			'vertical': {
				flexDirection: 'column',
				padding: '20px',
				gap: '24px',
			},
			'horizontal-wrap': {
				alignItems: 'center',
				padding: '12px',
				gap: '16px',
				flexWrap: 'wrap',
			},
			'horizontal-hero': {
				alignItems: 'center',
				padding: '28px',
				gap: '16px',
			},
			'vertical-hero': {
				flexDirection: 'column',
				padding: '28px',
				gap: '24px',
			},
			'horizontal-hero-wrap': {
				alignItems: 'center',
				padding: '28px',
				gap: '16px',
				flexWrap: 'wrap',
			},
		},
		clickable: {
			true: {
				cursor: {
					hover: 'pointer',
					focus: 'pointer',
				},
				outlineWidth: {
					hover: 0,
					focus: 0,
				},
				backgroundColor: {
					default: 'var(--rcx-card-background-color, var(--rcx-color-surface-light, #ffffff))',
					hover: 'var(--rcx-color-surface-hover, #f2f3f5)',
					focus: 'var(--rcx-color-surface-hover, #f2f3f5)',
				},
			},
			false: {},
		},
	},
});

// end of generated

const Card = ({ horizontal, hero, clickable, className, children, ...props }: CardProps) => {
	const breakpoints = useBreakpoints();
	const isMobile = !breakpoints.includes('sm');
	const wrap = Boolean(horizontal && isMobile);

	// Listed in the order `Box` gave the `rcx-` props it used to take: each one went in front of the last
	const classes = [
		clickable && 'rcx-card__clickable',
		wrap && 'rcx-card__horizontal--wrap',
		hero && 'rcx-card__hero',
		!horizontal && 'rcx-card__vertical',
		horizontal && 'rcx-card__horizontal',
		'rcx-card',
		className,
	]
		.filter(Boolean)
		.join(' ');

	return (
		<CardFrame
			// The caller's attributes go on the element `render` names: zero-runtime rejects spreads on a frame
			render={<Box {...props} />}
			layout={`${horizontal ? 'horizontal' : 'vertical'}${hero ? '-hero' : ''}${wrap ? '-wrap' : ''}`}
			clickable={Boolean(clickable)}
			className={classes}
		>
			{children}
		</CardFrame>
	);
};

export default Card;
